// app/actions.js
'use server';

import { prisma } from '@/lib/prisma';
import { revalidatePath } from 'next/cache';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { z } from 'zod';

const commentSchema = z.object({
  text: z.string().min(1, 'Comment cannot be empty').max(500),
});

export async function addComment(postSlug, formData) {
  const session = await getServerSession(authOptions);
  if (!session) {
    return { error: 'You must be signed in to comment.' };
  }

  const text = formData.get('text');
  const result = commentSchema.safeParse({ text });
  if (!result.success) {
    return { errors: result.error.flatten().fieldErrors };
  }

  const post = await prisma.post.findUnique({ where: { slug: postSlug } });
  if (!post) return { error: 'Post not found.' };

  await prisma.comment.create({
    data: {
      text: result.data.text,
      postId: post.id,
      userId: session.user.id,
    },
  });

  revalidatePath(`/posts/${postSlug}`);
  return { success: true };
}

// components/CommentForm.js
'use client';

import { useSession, signIn } from 'next-auth/react';
import { useFormState } from 'react-dom';
import { addComment } from '@/app/actions';

const initialState = {};

export default function CommentForm({ postSlug }) {
  const { data: session, status } = useSession();
  const addCommentWithSlug = addComment.bind(null, postSlug);
  const [state, formAction] = useFormState(addCommentWithSlug, initialState);

  if (status === 'loading') return <p>Loading...</p>;
  if (!session) {
    return (
      <button onClick={() => signIn()}>
        Sign in to leave a comment
      </button>
    );
  }

  return (
    <form action={formAction}>
      <textarea name="text" placeholder="Write a comment..." />
      {state?.errors?.text && <span className="error">{state.errors.text[0]}</span>}
      <button type="submit">Post Comment</button>
      {state?.success && <p className="success">Comment added!</p>}
      {state?.error && <p className="error">{state.error}</p>}
    </form>
  );
}

